go
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"testing"
)

func hashCertificate(cert string) string {
	hash := sha256.New()
	hash.Write([]byte(cert))
	return hex.EncodeToString(hash.Sum(nil))
}

func TestHashCertificate(t *testing.T) {
	tests := []struct {
		name     string
		cert     string
		expected string
	}{
		{
			name:     "Empty Certificate",
			cert:     "",
			expected: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
		},
		{
			name:     "Test Certificate",
			cert:     "test-certificate",
			expected: "9f86d081884c7d659a2feaa0c55ad23a3bf4f1b2b0b822cd15d6c15b0f00a08",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			actual := hashCertificate(tt.cert)
			if actual != tt.expected {
				t.Errorf("hashCertificate() = %v, want %v", actual, tt.expected)
			}
		})
	}
}
